    int n = length;
    if (n > path.length) {
      n = path.length;
    }
    int total = n;
    int nonempty = 0;
    int chars = 0;
    for (int i = 0; i < n; i++) {
      String part = path[i];
      if (part != null) {
        nonempty++;
        chars += part.length();
